function projectOpts(){return [{value:'',label:'Personal / unassigned'},...state.projects.map(p=>({value:p.id,label:`${p.title} (${sourceDisplayId(p)})`}))]}
function personOpts(){return [{value:'',label:'Select person'},...state.people.map(p=>({value:p.id,label:`${p.name} (${p.id})`}))]}
function questionOpts(){return [{value:'',label:'Select question'},...state.questions.map(q=>({value:q.id,label:`${q.id} — ${q.question.slice(0,70)}`}))]}
function taskOpts(){return [{value:'',label:'No linked task'},...state.tasks.map(t=>({value:t.id,label:`${t.id} — ${t.title.slice(0,70)}`}))]}
function sourceOpts(){return [{value:'',label:'Select source'},...state.sources.map(p=>({value:p.id,label:`${p.title} (${p.id})`}))]}
function customModal(title,body,onSubmit,submitLabel='Save'){modalAction=onSubmit;$('modalTitle').textContent=title;$('modalBody').innerHTML=`<form id="editorForm">${body}<div class="modal-foot"><button type="button" class="btn" data-close>Cancel</button><button type="submit" class="btn primary">${esc(submitLabel)}</button></div></form>`;$('modalBackdrop').classList.remove('hidden');document.body.style.overflow='hidden';$('editorForm').querySelector('input:not([type=hidden]),select,textarea')?.focus()}
function closeModal(){modalAction=null;$('modalBackdrop').classList.add('hidden');document.body.style.overflow=''}
async function db(){if(fileDb)return fileDb;fileDb=await new Promise((resolve,reject)=>{const req=indexedDB.open(FILE_DB,1);req.onupgradeneeded=()=>req.result.createObjectStore('files',{keyPath:'id'});req.onsuccess=()=>resolve(req.result);req.onerror=()=>reject(req.error)});return fileDb}
async function putFile(id,f){const d=await db();await new Promise((resolve,reject)=>{const tx=d.transaction('files','readwrite');tx.objectStore('files').put({id,name:f.name,type:f.type||'application/octet-stream',blob:f});tx.oncomplete=resolve;tx.onerror=()=>reject(tx.error)})}
async function getFile(id){const d=await db();return await new Promise((resolve,reject)=>{const t=d.transaction('files','readonly');const q=t.objectStore('files').get(id);q.onsuccess=()=>resolve(q.result||null);q.onerror=()=>reject(q.error)})}
async function allFiles(){const d=await db();return await new Promise((resolve,reject)=>{const q=d.transaction('files','readonly').objectStore('files').getAll();q.onsuccess=()=>resolve(q.result||[]);q.onerror=()=>reject(q.error)})}
async function deleteFile(id){const d=await db();await new Promise((resolve,reject)=>{const tx=d.transaction('files','readwrite');tx.objectStore('files').delete(id);tx.oncomplete=resolve;tx.onerror=()=>reject(tx.error)})}
function editor(type,id=''){const old=id?record(type,id):null;const oldStatus=old?.status;let values=old?{...old}:{id:idFor(type),category:type==='source'?'o':'',projectId:state.settings.activeProject||'',status:type==='source'?'—':type==='person'?'Unreviewed':type==='task'?'Not started':type==='project'?'Active':type==='claim'?'Unreviewed':'',date:today(),rate:state.settings.defaultRate,billable:false,peopleIds:[],supportIds:[],opposeIds:[],memberIds:[]};if(type==='session'&&old){values.date=isoLocal(old.startedAt).slice(0,10);values.minutes=Number(mins(old.durationMs).toFixed(2))}if(type==='project'&&!old)values.type='Personal genealogy';if(type==='source'&&old){values.personId=sourcePersonGuess(old);values.category=sourceCategoryGuess(old)||'';}const fields=defs[type];if(!fields){toast('Unknown editor');return}const timerBridge=type==='session'&&!old?`<div class="callout" style="margin-bottom:16px"><strong>Track this session with the timer:</strong> enter the project, person, work type and task, then use the timer instead of typing minutes. <button class="btn small" type="button" id="useSessionTimer" style="margin-left:9px">${state.timer.mode==='idle'?'▶ Start timer from this entry':'■ Finish active timer'}</button></div>`:'';const html=`${timerBridge}<div class="form-grid">${fields.map(f=>f.type==='file'?`<div class="field full"><label for="f-localFile">${esc(f.label)}</label><input type="file" id="f-localFile" name="localFile" accept=".pdf,.jpg,.jpeg,.png,.webp,.txt,.doc,.docx,.tif,.tiff">${values.fileName?`<span class="hint">Current attachment: ${esc(values.fileName)} (replacing does not change the Drive original)</span>`:''}<span class="hint">${esc(f.hint||'')}</span></div>`:field({...f,readonly:(type==='source'&&['id','publicId'].includes(f.name))||!!old&&f.name==='id',options:typeof f.options==='function'?f.options():f.options},values[f.name])).join('')}</div>`;
customModal(`${old?'Edit':'Add'} ${type}`,html,async fd=>{const obj={...values};for(const f of fields){if(f.type==='file')continue;if(f.type==='checkbox')obj[f.name]=fd.has(f.name);else if(f.type==='peopleMulti'||f.type==='sourcesMulti')obj[f.name]=fd.getAll(f.name);else if(f.type==='number')obj[f.name]=Number(fd.get(f.name)||0);else obj[f.name]=String(fd.get(f.name)||'').trim()}
if(type==='source'){
 const proposed=nextPersonSourceId(obj.personId,obj.category,old?.id||'');
 if(!proposed){toast('Select a primary person with a numbered ID and category');return false}
 if(old?.publicId&&old.publicId!==proposed&&!confirm('Change source number from '+old.publicId+' to '+proposed+'? Links stay intact.'))return false;
 obj.publicId=proposed;obj.peopleIds=[...new Set([obj.personId,...(obj.peopleIds||[])])];
}
if(!obj.id||!(obj.name||obj.title||obj.statement||obj.question||type==='relationship'||type==='session'||type==='event'||type==='household'||type==='expense'||type==='invoice')){toast('Complete all required fields');return false}
if(state[collection[type]].some(x=>x.id===obj.id&&x!==old)){toast('This record ID is already in use');return false}
if(type==='relationship'&&(!obj.fromId||!obj.toId||obj.fromId===obj.toId)){toast('Choose two different people');return false}
if(type==='source'&&obj.status==='R'&&(!obj.citation||(!obj.url&&!obj.downloadVerified&&!fd.get('localFile')?.size)||!obj.notes)){toast('Review needs a citation, an original location or saved copy, and documented findings');return false}
if(type==='source'&&obj.status==='Cx'&&!obj.notes){toast('Document the unresolved conflict in the findings field');return false}
if(type==='document'&&obj.url&&state.documents.some(x=>x!==old&&x.url===obj.url)){toast('Document already registered; use the existing intake record');return false}
if(['document','bookmark','task','inbox'].includes(type)&&obj.url&&!safeURL(obj.url)){toast('Enter a valid http or https link');return false}
if(type==='task'&&obj.attachmentUrl&&!safeURL(obj.attachmentUrl)){toast('Enter a valid document link');return false}
if(type==='session'){if(obj.workClass==='Assistant-only')obj.billable=false;if(!obj.minutes||obj.minutes<=0){toast('Duration must be greater than zero');return false}obj.durationMs=Math.round(obj.minutes*60000);const originalDay=old?.startedAt?isoLocal(old.startedAt).slice(0,10):'';const originalClock=old?.startedAt?isoLocal(old.startedAt).slice(11,16):'12:00';obj.startedAt=(old&&obj.date===originalDay)?old.startedAt:new Date(obj.date+'T'+originalClock+':00').toISOString();obj.endedAt=(old&&obj.date===originalDay&&obj.durationMs===old.durationMs)?old.endedAt:new Date(new Date(obj.startedAt).getTime()+obj.durationMs).toISOString();obj.method=old?.method||'manual';delete obj.minutes;delete obj.date}
const uploaded=fd.get('localFile');if(type==='source'&&uploaded instanceof File&&uploaded.size){try{await putFile(obj.id,uploaded);obj.fileName=uploaded.name;obj.fileType=uploaded.type}catch(e){toast('Attachment could not be saved; record was not changed');return false}}
obj.updatedAt=new Date().toISOString();if(!old){obj.createdAt=obj.updatedAt;state[collection[type]].push(obj)}else Object.assign(old,obj);if(type==='task')syncTaskClosure(old||obj,oldStatus||'Not started');save(`${old?'Updated':'Created'} ${type} ${obj.id}`);toast(`${type[0].toUpperCase()+type.slice(1)} saved`);render();return true},old?'Save changes':'Create record');
if(type==='source'){
 const idInput=$('f-publicId'),personInput=$('f-personId'),categoryInput=$('f-category');
 const updatePreview=()=>{
  if(!idInput||!personInput||!categoryInput)return;
  idInput.value=nextPersonSourceId(personInput.value,categoryInput.value,old?.id||'');
  idInput.placeholder=personInput.value?'Unable to generate ID':'Select primary person to generate an ID';
 };
 personInput?.addEventListener('change',updatePreview);
 categoryInput?.addEventListener('change',updatePreview);
 updatePreview();
}
}
function workSummary(){const ss=scope('session');return {hours:ss.filter(s=>s.workClass!=='Assistant-only').reduce((a,s)=>a+mins(s.durationMs)/60,0),assistantHours:ss.filter(s=>s.workClass==='Assistant-only').reduce((a,s)=>a+mins(s.durationMs)/60,0),billable:ss.reduce((a,s)=>a+(s.billable&&s.workClass!=='Assistant-only'?mins(s.durationMs)/60*Number(s.rate||0):0),0),expenses:scope('expense').reduce((a,e)=>a+Number(e.amount||0),0)}}
/* PRB productivity and research extensions — same local workspace; no new task store. */
const taskClosed=t=>['Completed','Cancelled'].includes(t.status);
const isWaiting=t=>['Waiting on response','Waiting','Awaiting response'].includes(t.status);
const isoDay=d=>{if(!d)return '';const x=new Date(d);return Number.isNaN(x.getTime())?'':x.toISOString().slice(0,10)};
const shiftDate=(s,unit)=>{if(!/^\d{4}-\d{2}-\d{2}$/.test(s||''))s=today();const d=new Date(s+'T12:00:00Z');const original=d.getUTCDate();switch(unit){case 'Daily':d.setUTCDate(d.getUTCDate()+1);break;case 'Weekly':d.setUTCDate(d.getUTCDate()+7);break;case 'Monthly':d.setUTCDate(1);d.setUTCMonth(d.getUTCMonth()+1);d.setUTCDate(Math.min(original,new Date(Date.UTC(d.getUTCFullYear(),d.getUTCMonth()+1,0)).getUTCDate()));break;case 'Yearly':d.setUTCFullYear(d.getUTCFullYear()+1);break;default:return ''}return d.toISOString().slice(0,10)};
function taskGroup(t){if(taskClosed(t))return t.status==='Completed'?'completed':'cancelled';const d=t.dueDate||'';const f=t.followupDate||'';const now=today();if(f&&f<now)return 'missed';if(d&&d<now)return 'overdue';if(d===now||f===now)return 'today';if(isWaiting(t))return 'waiting';if(d||f)return 'upcoming';return 'unscheduled'}
function taskBuckets(){const ts=scope('task');return {today:ts.filter(t=>taskGroup(t)==='today'),overdue:ts.filter(t=>taskGroup(t)==='overdue'),missed:ts.filter(t=>taskGroup(t)==='missed'),waiting:ts.filter(t=>isWaiting(t)&&!taskClosed(t)),upcoming:ts.filter(t=>taskGroup(t)==='upcoming'),completed:ts.filter(t=>t.status==='Completed'),recurring:ts.filter(t=>t.recurrence&&t.recurrence!=='None'),unscheduled:ts.filter(t=>taskGroup(t)==='unscheduled')}}
function syncTaskClosure(t,oldStatus){const wasClosed=['Completed','Cancelled'].includes(oldStatus);const nowClosed=taskClosed(t);if(!wasClosed&&nowClosed){t.completedAt=t.status==='Completed'?new Date().toISOString():'';t.completionDate=t.status==='Completed'?today():'';if(t.status==='Completed'&&t.recurrence&&!['None',''].includes(t.recurrence)&&!t.nextOccurrenceId){const nextDate=shiftDate(t.dueDate||today(),t.recurrence);if(nextDate){let due=nextDate,guard=0;while(due<=today()&&guard++<500){const advanced=shiftDate(due,t.recurrence);if(!advanced||advanced===due)break;due=advanced}const next={...t,id:idFor('task'),title:t.title,status:'Not started',completedAt:'',completionDate:'',dueDate:due,followupDate:'',parentTaskId:t.parentTaskId||'',recurringFrom:t.recurringFrom||t.id,nextOccurrenceId:'',createdAt:new Date().toISOString(),updatedAt:new Date().toISOString()};state.tasks.push(next);t.nextOccurrenceId=next.id;}}}else if(wasClosed&&!nowClosed){t.completedAt='';t.completionDate='';}}
function updateTaskStatus(id,nextStatus){const t=record('task',id);if(!t)return;const previous=t.status;if(previous===nextStatus)return;const backup=JSON.stringify(state);t.status=nextStatus;t.updatedAt=new Date().toISOString();syncTaskClosure(t,previous);save('Updated task '+t.id+' → '+nextStatus);if(!storageOK){state=normalize(JSON.parse(backup));toast('Task change was not saved');return}render();toast(nextStatus==='Completed'?'Task completed':'Task updated')}
function taskRow(t,compact=false){const g=taskGroup(t);const desc=t.description||t.notes||'';const hint=[t.dueDate?`Due ${t.dueDate}${t.dueTime?' '+t.dueTime:''}`:'',t.followupDate?`Follow-up ${t.followupDate}`:'',t.assignedTo?`Assigned: ${t.assignedTo}`:''].filter(Boolean).join(' · ');return `<div class="soft-row task-row"><div class="grow" style="min-width:0"><div class="flex flex-wrap"><strong>${esc(t.title)}</strong><span class="pill ${g==='overdue'||g==='missed'?'Cx':''}">${esc(g==='missed'?'Missed follow-up':g==='overdue'?'Overdue':t.status||'Not started')}</span></div><small>${esc(t.id)} · ${esc(label('project',t.projectId))}${hint?' · '+esc(hint):''}</small>${!compact&&desc?`<small>${esc(desc.slice(0,220))}</small>`:''}</div><div class="flex flex-wrap"><button class="btn small" data-edit="task:${esc(t.id)}">Edit</button>${!taskClosed(t)?`<button class="btn small" data-task-complete="${esc(t.id)}" title="Clear resolved priority; retain task history">✓ Clear</button>`:''}${isWaiting(t)||t.followupDate?`<button class="btn small" data-task-followup="${esc(t.id)}">+ Follow-up</button>`:''}${!compact&&!taskClosed(t)?`<button class="btn small" data-task-track="${esc(t.id)}">◷ Time</button>`:''}</div></div>`}
let todoTab='today',researchTab='questions',referenceSearch='',bookmarkQuery='',docQuery='';
function renderTodo(){const b=taskBuckets();const tabs=[['today','Today',b.today.length],['overdue','Overdue',b.overdue.length],['missed','Missed follow-ups',b.missed.length],['upcoming','Upcoming',b.upcoming.length],['waiting','Waiting On',b.waiting.length],['recurring','Recurring',b.recurring.length],['completed','Completed',b.completed.length],['unscheduled','Unscheduled',b.unscheduled.length]];const show=todoTab==='waiting'?b.waiting:todoTab==='recurring'?b.recurring:b[todoTab]||[];content(intro('To-Do','Your daily checklist. This and Tasks edit the same records.',`<div class="flex flex-wrap"><button class="btn" data-quick-capture="task">+ Quick Add</button><button class="btn primary" data-research-start>▶ Research session</button></div>`)+`<div class="grid stats">${stat('Due today',b.today.length,'Next actions')}${stat('Overdue',b.overdue.length,'Past due, still open')}${stat('Missed follow-ups',b.missed.length,'Response checks missed')}${stat('Waiting on replies',b.waiting.length,'Not completed')}</div><section class="card"><div class="tabstrip">${tabs.map(([key,title,n])=>`<button class="${todoTab===key?'active':''}" data-todo-tab="${key}">${esc(title)} (${n})</button>`).join('')}</div><div class="stack">${show.length?show.sort((a,b)=>String(a.dueDate||a.followupDate||'9999').localeCompare(b.dueDate||b.followupDate||'9999')).map(t=>taskRow(t)).join(''):empty('Nothing in this view','Use Quick Add to add a task, or switch to another view.')}</div></section><section class="card"><h3 class="section-title block-heading">Task Inbox</h3>${inboxRows(true)}</section>`)}
function dashboardTodo(){const b=taskBuckets(),now=state.timer.mode!=='idle',active=scope('project').filter(p=>['Active','Planning','In progress'].includes(p.status));const last=t=>t.sort((a,b)=>String(a.dueDate||a.followupDate||'9999').localeCompare(String(b.dueDate||b.followupDate||'9999')))[0];const groups=[['Today',b.today],['Overdue',b.overdue],['Missed follow-ups',b.missed],['Waiting on replies',b.waiting],['Upcoming deadlines',b.upcoming]];return `<section class="card" style="margin-bottom:18px"><div class="split block-heading"><h3 class="section-title">Today's To-Do</h3><div class="flex"><button class="btn small" data-quick-capture="task">+ Quick Add</button><button class="btn small" data-quick-capture="idea">Capture idea</button><button class="btn small" data-nav="todo">Open To-Do</button></div></div>${groups.map(([title,items])=>`<div class="section-gap"><div class="split"><strong>${esc(title)} (${items.length})</strong></div>${items.length?items.slice(0,3).map(x=>taskRow(x,true)).join(''):'<p class="muted small-text">None</p>'}</div>`).join('')}${now?`<div class="callout"><strong>Timer running:</strong> ${esc(state.timer.task||'Research session')} · ${esc(label('project',state.timer.projectId))}<button class="btn small" data-timer-finish style="margin-left:8px">Finish / review</button></div>`:''}${active.length?`<h4 style="margin-top:15px">Active project next actions</h4>${active.slice(0,8).map(p=>{let t=last(state.tasks.filter(t=>t.projectId===p.id&&!taskClosed(t)));return `<div class="soft-row"><strong>${esc(p.title)}</strong>${t?`<button class="link-btn" data-edit="task:${esc(t.id)}">${esc(t.title)} (${esc(t.id)})</button>`:`<button class="btn small" data-new-for-project="${esc(p.id)}">+ Next action</button>`}</div>`}).join('')}`:''}</section>`}
function createQuickTask(){customModal('Quick Add task',`<div class="form-grid"><div class="field full"><label for="quickTitle">Task title *</label><input id="quickTitle" name="title" required></div><div class="field"><label>Project</label><select name="projectId">${projectSelect(state.settings.activeProject,'No project')}</select></div><div class="field"><label>Due date</label><input type="date" name="dueDate" value="${today()}"></div><div class="field"><label>Priority</label><select name="priority"><option>Medium</option><option>High</option><option>Low</option></select></div><div class="field"><label>Follow-up date (optional)</label><input type="date" name="followupDate"></div><div class="field full"><label>Notes</label><textarea name="notes"></textarea></div></div>`,fd=>{const title=String(fd.get('title')||'').trim();if(!title)return false;const now=new Date().toISOString();const t={id:idFor('task'),title,projectId:String(fd.get('projectId')||''),dueDate:String(fd.get('dueDate')||''),priority:String(fd.get('priority')||'Medium'),followupDate:String(fd.get('followupDate')||''),notes:String(fd.get('notes')||''),status:'Not started',recurrence:'None',createdAt:now,updatedAt:now};state.tasks.push(t);save('Quick added task '+t.id);if(!storageOK){state.tasks.pop();return false}render();return true},'Add task')}
function createFollowup(parent){const p=record('task',parent);if(!p)return;customModal('Create linked follow-up',`<p class="muted small-text">This creates a separate linked task; it does not close or replace ${esc(p.id)}.</p><div class="form-grid"><div class="field full"><label>Follow-up action *</label><input name="title" required value="${esc('Follow up: '+p.title)}"></div><div class="field"><label>Due date</label><input type="date" name="dueDate" value="${esc(p.followupDate||today())}"></div><div class="field"><label>Contact / organization</label><input name="contact" value="${esc(p.contact||'')}"></div><div class="field full"><label>Notes / request</label><textarea name="notes">${esc(p.requestedInfo||'')}</textarea></div></div>`,fd=>{const title=String(fd.get('title')||'').trim();if(!title)return false;const t={id:idFor('task'),projectId:p.projectId||'',personId:p.personId||'',sourceId:p.sourceId||'',parentTaskId:p.id,title,contact:String(fd.get('contact')||''),notes:String(fd.get('notes')||''),dueDate:String(fd.get('dueDate')||''),status:'Not started',priority:p.priority||'Medium',createdAt:new Date().toISOString()};state.tasks.push(t);save('Created follow-up '+t.id+' for '+p.id);render();toast('Follow-up created; original task unchanged');return true},'Create follow-up')}
function inboxRows(short=false){const rows=scope('inbox').filter(x=>x.status!=='Triaged');return `${rows.length?rows.slice(0,short?4:80).map(x=>`<div class="soft-row"><div class="grow"><strong>${esc(x.title)}</strong><small>${esc(x.kind||'Idea')} · ${esc(x.createdAt?localTime(x.createdAt):'')} ${x.url?`· <a href="${esc(safeURL(x.url))}" target="_blank" rel="noopener noreferrer">Link ↗</a>`:''}</small>${!short&&x.notes?`<small>${esc(x.notes)}</small>`:''}</div><button class="btn small" data-inbox-triage="${esc(x.id)}">Triage</button></div>`).join(''):empty('Inbox clear','Quick Capture collects new research items here.')}${short&&rows.length>4?`<button class="btn small" data-nav="research">View all ${rows.length}</button>`:''}`}
function quickCapture(kind='idea'){const kinds=['Task','Research idea','Question','Lead','Person','Source','Website','Document to review'];const defaultKind={'idea':'Research idea','task':'Task','document':'Document to review','question':'Question'}[kind]||kind;customModal('Quick Capture',`<div class="form-grid"><div class="field"><label>Capture type</label><select name="kind">${kinds.map(k=>`<option ${k===defaultKind?'selected':''}>${esc(k)}</option>`).join('')}</select></div><div class="field"><label>Project</label><select name="projectId">${projectSelect(state.settings.activeProject,'Inbox / unassigned')}</select></div><div class="field full"><label>What needs attention? *</label><input name="title" required></div><div class="field full"><label>Website / document link</label><input name="url" type="url" placeholder="https://"></div><div class="field full"><label>Notes</label><textarea name="notes"></textarea></div></div>`,fd=>{const title=String(fd.get('title')||'').trim();if(!title)return false;const kind=String(fd.get('kind')||'Research idea');const url=String(fd.get('url')||'');if(url&&!safeURL(url)){toast('Use a valid https:// or http:// link');return false}const projectId=String(fd.get('projectId')||'');const notes=String(fd.get('notes')||'');if(kind==='Task'){state.tasks.push({id:idFor('task'),projectId,title,notes,attachmentUrl:url,status:'Not started',priority:'Medium',createdAt:new Date().toISOString()});save('Quick captured task');}else{state.inbox.push({id:idFor('inbox'),projectId,kind,title,url,notes,status:'New',createdAt:new Date().toISOString()});save('Captured '+kind+' to Inbox');}render();return true},'Capture')}
function triageInbox(id){const item=record('inbox',id);if(!item)return;const options=[['Task','task'],['Research Question','question'],['Person','person'],['Source','source'],['Document','document'],['Bookmark','bookmark']];const preferred={'Question':'question','Person':'person','Source':'source','Document to review':'document','Website':'bookmark','Lead':'task','Research idea':'question'}[item.kind]||'task';const html=`<p class="muted">Create a linked record or mark this item reviewed. The original capture stays in history.</p><div class="field"><label>Send to</label><select name="type">${options.map(([name,k])=>`<option value="${k}" ${k===preferred?'selected':''}>${name}</option>`).join('')}</select></div>`;customModal('Triage: '+item.title,html,fd=>{const type=String(fd.get('type')||preferred);const values={id:idFor(type),projectId:item.projectId||'',title:item.title,name:item.title,question:item.title,notes:item.notes||'',description:item.notes||'',url:item.url||'',status:type==='document'?'Unreviewed':type==='task'?'Not started':'',createdAt:new Date().toISOString()};if(type==='bookmark')values.name=item.title;if(type==='source')values.status='—';if(type==='question')values.status='Open';if(type==='person')values.status='Unreviewed';if(type==='task')values.priority='Medium';state[collection[type]].push(values);item.status='Triaged';item.linkedId=values.id;save('Triaged inbox '+id+' to '+values.id);render();editor(type,values.id);return true},'Create linked record')}
function renderQuestions(){return `<div class="split block-heading"><h3 class="section-title">Research questions</h3>${newBtn('question','New question')}</div>${scope('question').length?scope('question').map(q=>`<div class="soft-row"><div class="grow"><strong>${esc(q.question)}</strong><small>${esc(q.id)} · ${esc(label('project',q.projectId))} · ${esc(q.status||'Open')}</small>${q.missing?`<small>Missing: ${esc(q.missing)}</small>`:''}</div><button class="btn small" data-edit="question:${esc(q.id)}">Edit</button><button class="btn small" data-research-question="${esc(q.id)}">▶ Work</button></div>`).join(''):empty('No research questions','Create a question before logging a search.','question')}`}
function renderResearch(){const tabs=[['questions','Questions'],['logs','Search log'],['workspace','Session workspace'],['followups','Follow-ups'],['bookmarks','Bookmarks'],['inbox','Inbox']];let html=intro('Research workspace','Question → search → evidence → next action. Record dead ends so they are not repeated.',`<button class="btn primary" data-research-start>▶ Start Research Session</button>`)+`<section class="card"><div class="tabstrip">${tabs.map(([id,name])=>`<button class="${researchTab===id?'active':''}" data-research-tab="${id}">${name}</button>`).join('')}</div>`;
if(researchTab==='questions')html+=renderQuestions();
else if(researchTab==='logs')html+=`<div class="split block-heading"><h3 class="section-title">Research log</h3>${newBtn('search','Log search')}</div>${scope('search').length?scope('search').slice().sort((a,b)=>String(b.date||'').localeCompare(String(a.date||''))).map(x=>`<div class="soft-row"><div class="grow"><strong>${esc(x.question||x.query||'Search')}</strong><small>${esc(x.date||'')} · ${esc(x.repository||'')} · ${esc(x.result||'Not started')}</small>${x.findings?`<small>${esc(x.findings.slice(0,250))}</small>`:''}<small>Sources: ${esc((x.sourceIds||[x.sourceId].filter(Boolean)).join(', ')||'None linked')}</small></div><button class="btn small" data-edit="search:${esc(x.id)}">Edit</button></div>`).join(''):empty('No searches logged','Record successful and unsuccessful search attempts.','search')}`;
else if(researchTab==='workspace')html+=`<h3 class="section-title block-heading">Research session</h3>${state.timer.mode!=='idle'?`<div class="callout"><strong>${esc(state.timer.task)}</strong><p>Project: ${esc(label('project',state.timer.projectId))} · Question: ${esc(label('question',state.timer.questionId))}</p><button class="btn" data-timer-finish>Finish and review research session</button></div><div class="grid cols-2" style="margin-top:14px"><button class="btn" data-new="search">+ Log a search or negative finding</button><button class="btn" data-new="source">+ Register a source</button><button class="btn" data-new="claim">+ Link evidence</button><button class="btn" data-quick-capture="idea">+ Capture lead</button></div>`:empty('No active session','Start a research session to connect project, question, timer, and findings.')}<h4>Recent sessions</h4>${dateSort(scope('session'),'startedAt').slice(0,5).map(x=>`<div class="soft-row"><strong>${esc(x.task)}</strong><small>${esc(day(x.startedAt))} · ${esc(duration(x.durationMs))}</small><button class="btn small" data-edit="session:${esc(x.id)}">Open</button></div>`).join('')}`;
else if(researchTab==='followups')html+=`<h3 class="section-title block-heading">Correspondence and follow-ups</h3><div class="callout">Follow-up requests are Tasks records. New follow-ups link to the original task instead of closing or replacing it.</div>${scope('task').filter(t=>t.contact||t.followupDate||isWaiting(t)).map(t=>taskRow(t)).join('')||empty('No follow-ups yet','Create a task with contact information or a follow-up date.','task')}`;
else if(researchTab==='bookmarks')html+=`<div class="split block-heading"><h3 class="section-title">Research bookmarks</h3>${newBtn('bookmark','Add bookmark')}</div>${bookmarkList()}`;
else html+=`<div class="split block-heading"><h3 class="section-title">Quick Capture Inbox</h3><button class="btn" data-quick-capture="idea">+ Capture</button></div>${inboxRows(false)}`;
content(html+'</section>')}
function startResearchSession(questionId=''){if(state.timer.mode!=='idle'){researchTab='workspace';navigate('research');toast('A timer is already active; finish it before starting another.');return}const q=record('question',questionId);customModal('Start Research Session',`<div class="form-grid"><div class="field"><label>Project</label><select name="projectId" id="rsProject">${projectSelect(q?.projectId||state.settings.activeProject,'Personal / no project')}</select></div><div class="field"><label>Research question</label><select name="questionId" id="rsQuestion"><option value="">Unassigned</option>${state.questions.map(x=>`<option value="${esc(x.id)}" ${x.id===questionId?'selected':''}>${esc(x.id)} — ${esc(x.question.slice(0,80))}</option>`).join('')}</select></div><div class="field full"><label>Work / task description *</label><input name="task" required value="${esc(q?.question||'')}" placeholder="What will you investigate?"></div><div class="field"><label>Work type</label><select name="workType"><option>Research</option><option>Record processing</option><option>Evidence analysis</option><option>Appraisal research</option></select></div><div class="field"><label>Hourly rate ($)</label><input name="rate" type="number" min="0" step=".01" value="${esc(state.settings.defaultRate)}"></div><div class="field full"><label class="check-option"><input name="saveToTimesheet" type="checkbox" checked> Save recorded time to existing Timesheet</label></div></div>`,fd=>{const qid=String(fd.get('questionId')||'');const detail=String(fd.get('task')||'').trim()||record('question',qid)?.question;if(!detail)return false;const ok=startTimer({projectId:String(fd.get('projectId')||''),questionId:qid,task:detail,workType:String(fd.get('workType')||'Research'),workClass:'Hands-on',rate:Number(fd.get('rate'))||0,saveToTimesheet:fd.has('saveToTimesheet')});if(!ok)return false;researchTab='workspace';navigate('research');return true},'Start timer and open workspace')}
function bookmarkList(){let b=scope('bookmark').filter(x=>(`${x.title||''} ${x.url||''} ${x.notes||''}`).toLowerCase().includes(bookmarkQuery.toLowerCase()));return `<input class="search" id="bookmarkSearch" placeholder="Search bookmarks…" value="${esc(bookmarkQuery)}">${b.length?b.map(x=>`<div class="soft-row"><div class="grow"><strong>${esc(x.title||x.name)}</strong><small>${esc(x.category||'Research tool')} · ${esc(label('project',x.projectId))}</small>${x.url&&safeURL(x.url)?`<a href="${esc(safeURL(x.url))}" target="_blank" rel="noopener noreferrer">Open site ↗</a>`:''}</div>${actions('bookmark',x.id)}</div>`).join(''):empty('No bookmarks','Save genealogy databases, archives, and research tools.','bookmark')}`}
const researchTemplates=[
{key:'personal',name:'Personal genealogy',type:'Personal genealogy',qs:['Which sources establish each identity and relationship?','Which dates and places have independent records?'],steps:['Review R00 people and existing source registers','Search vital, census and local records; log negative results','Evaluate conflicting relationships and write a proof summary']},
{key:'client',name:'Client genealogy',type:'Client genealogy',qs:['What is the documented relationship or lineage requested by the client?','What identifiers or vital records are missing?'],steps:['Confirm written scope, consent, privacy and deliverables','Document search coverage and cite each finding','Review and prepare a client-safe genealogy report']},
{key:'history',name:'Historical investigation',type:'Historical investigation',qs:['Which records establish the historical event or person?','What alternative accounts or archival gaps remain?'],steps:['Define research period and places','Find primary collections and document failed searches','Compare sources and prepare an evidence report']},
{key:'provenance',name:'Provenance research',type:'Provenance / appraisal research',qs:['What is the documented chain of custody or ownership?','Which transfers, dates and identities lack corroboration?'],steps:['Identify the object and record physical descriptions','Build a documented ownership timeline with source IDs','Flag undocumented transfers and prepare a provenance summary']},
{key:'appraisal',name:'Appraisal documentation',type:'Provenance / appraisal research',qs:['What item attributes and comparable sales are documented?','What are the relevant valuation date and market context?'],steps:['Record object condition and ownership evidence','Collect comparables and their sources','Prepare research workpapers; do not claim a formal appraisal credential']},
{key:'archive',name:'Archival record request',type:'Historical investigation',qs:['What original record is needed and who holds it?'],steps:['Identify the record holder and exact item identifiers','Send request and set expected response and follow-up','Record results and preserve received file/citation']}
];
function applyTemplate(key){const t=researchTemplates.find(x=>x.key===key);if(!t)return;customModal('Create project from template',`<div class="callout">This creates an unverified planning checklist, not verified research findings.</div><div class="field"><label>New project title *</label><input required name="title" value="${esc(t.name)}"></div>`,fd=>{const title=String(fd.get('title')||'').trim();if(!title)return false;const p={id:idFor('project'),title,type:t.type,status:'Planning',privacy:'Personal/private',createdAt:new Date().toISOString()};state.projects.push(p);t.qs.forEach(q=>state.questions.push({id:idFor('question'),projectId:p.id,question:q,status:'Open',createdAt:new Date().toISOString(),notes:'Template prompt; not a verified finding'}));t.steps.forEach(s=>state.tasks.push({id:idFor('task'),projectId:p.id,title:s,status:'Not started',priority:'Medium',notes:'Template checklist; not evidence',createdAt:new Date().toISOString()}));save('Created template project '+p.id);render();toast('Project, questions, and tasks created');return true},'Create project & checklist')}
function renderDocuments(){let docs=scope('document').filter(x=>`${x.title||''} ${x.notes||''} ${x.url||''}`.toLowerCase().includes(docQuery.toLowerCase()));return `<section class="card"><div class="split block-heading"><div><h3 class="section-title">Document Inbox</h3><p class="muted small-text">Track new files and review metadata without moving or changing Drive originals.</p></div>${newBtn('document','Intake document')}</div><input class="search" id="documentSearch" placeholder="Find an intake record…" value="${esc(docQuery)}">${docs.length?docs.map(x=>`<div class="soft-row"><div class="grow"><strong>${esc(x.title)}</strong><small>${esc(x.id)} · ${esc(x.reviewStatus||'Unreviewed')} · ${esc(label('project',x.projectId))}</small>${x.url?`<a href="${esc(safeURL(x.url))}" target="_blank" rel="noopener noreferrer">Open original ↗</a>`:''}</div>${actions('document',x.id)}</div>`).join(''):empty('No documents in intake','Select an existing Drive file below or register an outside document.')}</section>`}
function intakeDriveFile(id){const f=(state.driveLibrary||[]).find(x=>x.id===id);if(!f)return;if(state.documents.some(d=>d.driveId===f.id||d.url===f.url)){toast('Already added to Document Inbox');return}const possible=state.documents.find(x=>String(x.title||'').toLowerCase().replace(/[^a-z0-9]/g,'')===String(f.name||'').toLowerCase().replace(/[^a-z0-9]/g,''));const d={id:idFor('document'),title:f.name,projectId:state.settings.activeProject||'',driveId:f.id,url:f.url||'',fileType:f.mime||'',reviewStatus:possible?'Duplicate candidate':'Unreviewed',duplicateOf:possible?.id||'',notes:'Original remains in Google Drive: '+f.path,peopleIds:[],createdAt:new Date().toISOString()};state.documents.push(d);save('Added Drive file '+id+' to Document Inbox');render();toast('Added to Document Inbox')}
function ownershipChain(){const ev=scope('event').filter(e=>e.eventType==='Ownership transfer'||e.asset);const grouped=new Map();ev.forEach(e=>{const k=e.asset||'Unspecified asset';if(!grouped.has(k))grouped.set(k,[]);grouped.get(k).push(e)});return `<div class="split block-heading"><h3 class="section-title">Property & provenance chains</h3>${newBtn('event','Add ownership event')}</div><div class="callout">Chains are built only from saved events. Gaps and missing source IDs remain visible; this does not prove ownership.</div>${grouped.size?[...grouped].map(([asset,items])=>`<section class="card"><h4>${esc(asset)}</h4><div class="timeline">${items.sort((a,b)=>String(a.date||'').localeCompare(String(b.date||''))).map(e=>`<div class="time-entry"><span class="pill">${esc(e.date||'Undated')}</span><p><strong>${esc(label('person',e.ownerFromId))}</strong> → <strong>${esc(label('person',e.ownerToId))}</strong></p><small>${esc(e.title)} · ${esc(e.place||'')}</small>${e.sourceId?`<button class="link-btn" data-edit="source:${esc(e.sourceId)}">Source ${esc(e.sourceId)}</button>`:'<span class="pill Cx">No source linked</span>'}<button class="btn small" data-edit="event:${esc(e.id)}">Open event</button></div>`).join('')}</div></section>`).join(''):empty('No ownership chain events','Add an event with an asset and ownership transfer.')}`}
function documentConnections(){
  const docs=scope('document').slice(0,32);
  if(!docs.length)return `<div class="split block-heading"><h3 class="section-title">Document-to-person network</h3>${newBtn('document','Intake document')}</div>`+empty('No document relationships','Link a document to a person or source in Document Inbox.','document');
  const ids=[...new Set(docs.flatMap(d=>d.peopleIds||[]))].filter(id=>record('person',id)).slice(0,40);
  const srcIds=[...new Set(docs.map(d=>d.sourceId).filter(Boolean))].filter(id=>record('source',id)).slice(0,30);
  const w=1040,h=Math.max(340,Math.max(docs.length,ids.length,srcIds.length)*67+110);
  const posD=new Map(docs.map((d,i)=>[d.id,{x:186,y:83+i*(h-130)/Math.max(1,docs.length-1)}]));
  const posP=new Map(ids.map((id,i)=>[id,{x:540,y:83+i*(h-130)/Math.max(1,ids.length-1)}]));
  const posS=new Map(srcIds.map((id,i)=>[id,{x:879,y:83+i*(h-130)/Math.max(1,srcIds.length-1)}]));
  let svg=svgHeader(w,h);
  svg+=`<text x="185" y="27" text-anchor="middle" font-size="16" fill="#355260">Documents</text><text x="540" y="27" text-anchor="middle" font-size="16" fill="#355260">People</text><text x="880" y="27" text-anchor="middle" font-size="16" fill="#355260">Sources</text>`;
  for(const d of docs){const a=posD.get(d.id);for(const id of d.peopleIds||[]){const b=posP.get(id);if(b)svg+=`<path d="M${a.x+116} ${a.y} C370 ${a.y},370 ${b.y},${b.x-116} ${b.y}" fill="none" stroke="#56879a" stroke-width="2"/>`;}const b=posS.get(d.sourceId);if(b)svg+=`<path d="M${a.x+116} ${a.y} C600 ${a.y},690 ${b.y},${b.x-116} ${b.y}" fill="none" stroke="#aa8661" stroke-dasharray="6 4" stroke-width="2"/>`;}
  const node=(id,title,x,y,type,color)=>`<g class="graph-node" role="button" tabindex="0" data-edit="${type}:${esc(id)}"><rect x="${x-116}" y="${y-23}" width="232" height="48" rx="9" fill="${color}" stroke="#819ca7"/><text x="${x}" y="${y-3}" text-anchor="middle" font-size="11" fill="#2a4556">${svgText(title,29)}</text><text x="${x}" y="${y+14}" text-anchor="middle" font-size="10" fill="#647981">${esc(id)}</text><title>${esc(title)} · open ${esc(type)}</title></g>`;
  for(const d of docs){const a=posD.get(d.id);svg+=node(d.id,d.title,a.x,a.y,'document','#f2f5f6')}
  for(const id of ids){const p=record('person',id),a=posP.get(id);svg+=node(id,p.name,a.x,a.y,'person','#e7f2f3')}
  for(const id of srcIds){const p=record('source',id),a=posS.get(id);svg+=node(id,p.title,a.x,a.y,'source','#fff5e6')}
  svg+='</svg>';
  return `<div class="split block-heading"><h3 class="section-title">Document-to-person and source network</h3>${newBtn('document','Intake document')}</div>`+graphWrap(svg,'Each line comes from a saved Document Inbox link. Click any document, person, or source to open its original record. Missing links remain visible as unconnected nodes.');
}
function financeOverview(){const projects=scope('project');const inv=scope('invoice');const paid=inv.filter(x=>x.status==='Paid').reduce((a,x)=>a+Number(x.amount||0),0),invoiced=inv.reduce((a,x)=>a+Number(x.amount||0),0);const hours=scope('session').filter(x=>x.workClass!=='Assistant-only').reduce((a,x)=>a+mins(x.durationMs)/60,0);return `<section class="card"><div class="split"><h3 class="section-title">Client billing and profitability</h3>${newBtn('invoice','New invoice')}</div><p class="muted small-text">Values are based on recorded invoices, paid amounts, tracked hours and expenses—not an accounting system or tax report. Internal labor costs require a separate project-level cost rate; billing rates are not treated as labor costs.</p><div class="grid stats">${stat('Invoiced',cash(invoiced),'Invoice ledger')}${stat('Received',cash(paid),'Marked paid')}${stat('Time logged',fmt(hours,2)+' h','Excludes assistant-only')}</div>${projects.map(p=>{const ses=state.sessions.filter(x=>x.projectId===p.id&&x.workClass!=='Assistant-only');const hrs=ses.reduce((a,x)=>a+mins(x.durationMs)/60,0);const laborRate=Number(p.laborCostRate||0);const laborKnown=Number.isFinite(laborRate)&&laborRate>0;const labor=laborKnown?hrs*laborRate:0;const costs=state.expenses.filter(x=>x.projectId===p.id).reduce((a,x)=>a+Number(x.amount||0),0);const bills=state.invoices.filter(x=>x.projectId===p.id);const receipts=bills.filter(x=>x.status==='Paid').reduce((a,x)=>a+Number(x.amount||0),0);const enough=!!(ses.length||costs||bills.length);return `<div class="soft-row"><div class="grow"><strong>${esc(p.title)}</strong><small>${fmt(hrs,2)} h · Expenses ${cash(costs)} · ${laborKnown?'Estimated internal labor cost '+cash(labor):'Internal labor cost not set'} · Paid ${cash(receipts)}</small></div><span class="pill">${enough?laborKnown&&bills.length?`Estimated profit ${cash(receipts-costs-labor)}`:`Cash after expenses ${cash(receipts-costs)} (not profit)`:'Insufficient records'}</span></div>`}).join('')}${inv.length?compactRows(inv,x=>`<tr><td>${esc(x.id)}</td><td>${esc(label('project',x.projectId))}</td><td>${cash(x.amount)}</td><td>${uiBadge(x.status)}</td><td>${actions('invoice',x.id)}</td></tr>`,['Invoice','Project','Amount','Status','Actions']):empty('No invoices','Paid client work can be tracked here later.')}</section>`}

