person:{title:'People register',desc:'Permanent R00 IDs, vital events, identity notes, and family associations.',cols:['Person','Birth','Death','Identity','Actions'],match:['id','name','aliases','notes','birthPlace','deathPlace'],render:r=>`<tr><td><span class="main-cell">${esc(r.name)}</span><br><small>${esc(r.id)} ${r.living?'· Living / private':''}</small></td><td>${esc(r.birthDate||'—')}<br><small>${esc(r.birthPlace||'')}</small></td><td>${esc(r.deathDate||'—')}</td><td>${uiBadge(r.status)}</td><td>${actions('person',r.id)}</td></tr>`},
source:{title:'Sources & documents',desc:'Save full citations, identify people, verify downloads, and preserve original source links.',cols:['Source','Type / repository','Source status','Preservation','Actions'],match:['title','id','publicId','repository','collection','citation','notes'],render:r=>`<tr><td><span class="main-cell">${esc(r.title)}</span><br><small>${esc(sourceDisplayId(r))}${r.publicId?' · Internal '+esc(r.id):' · Number pending'}</small>${r.url&&safeURL(r.url)?`<br><a class="safe-link" href="${esc(safeURL(r.url))}" target="_blank" rel="noopener noreferrer">Original / Drive link ↗</a>`:''}</td><td>${esc(r.type)}<br><small>${esc(r.repository||'')}</small></td><td>${uiBadge(r.status)}<br><small>${esc(statusLabels[r.status]||'')}</small></td><td>${r.downloadVerified?'✓ Verified':r.fileName?'In browser · not verified':'Needs verification'}${r.fileName?`<br><button class="link-btn" data-file="${esc(r.id)}">↓ ${esc(r.fileName)}</button>`:''}</td><td>${actions('source',r.id)}</td></tr>`},
search:{title:'Research log',desc:'Document the search, its exact coverage, negative results, and the next lead.',cols:['Date / log ID','Research question','Repository & search','Result','Actions'],match:['id','question','repository','query','findings','next'],render:r=>`<tr><td>${esc(r.date||'—')}<br><small>${esc(r.id)}</small></td><td class="main-cell">${esc(r.question)}</td><td>${esc(r.repository||'—')}<br><small>${esc(r.query||'')}</small></td><td>${uiBadge(r.result)}</td><td>${actions('search',r.id)}</td></tr>`},
