task:{title:'Research tasks',desc:'Keep open tasks visible together, including blocked records and exact next actions.',cols:['Task','Project / link','Priority','Status / due','Actions'],match:['id','title','notes','priority'],render:r=>`<tr><td><span class="main-cell">${esc(r.title)}</span><br><small>${esc(r.id)}</small></td><td>${esc(label('project',r.projectId))}<br><small>${esc(r.sourceId||r.personId||'')}</small></td><td>${uiBadge(r.priority)}</td><td>${uiBadge(r.status)}<br><small>${r.dueDate?'Due '+esc(r.dueDate):''}</small></td><td>${actions('task',r.id)} <button class="btn small" data-task-followup="${esc(r.id)}">+ Follow-up</button>${!taskClosed(r)?` <button class="btn small" data-task-track="${esc(r.id)}">◷ Time</button>`:''}</td></tr>`},
